STATUS_CODE = 'import json,hashlib,zipfile,base64,io\nfrom pathlib import Path\nfrom datetime import UTC,datetime\nfrom collections import Counter\nfrom IPython.display import HTML,display\noutput_dir=workspace/\'reports/cuda-eval2\'\nstatus_path=next((output_dir/n for n in [\'evaluation.json\',\'evaluation-partial.json\'] if (output_dir/n).is_file()),None)\nraw_status=status_path.read_bytes() if status_path else None\nactual=json.loads(raw_status) if raw_status else None\nif actual:\n    assert actual[\'run_id\']==\'resolvedesk-cuda-eval-002\'\n    assert actual[\'analysis_plan_sha256\']==EXPECTED_PLAN_SHA256\n    assert actual[\'execution_addendum_sha256\']==\'e6e72a162af8c140a83ef9cf4c13102c24afb7428905ade797e98463d14c0e3e\'\n    count=len(actual[\'records\'])\n    by_arm=dict(Counter(r[\'variant\'] for r in actual[\'records\']))\nelse:\n    count=0;by_arm={}\nraw_journal=(output_dir/\'call-journal.json\').read_bytes() if (output_dir/\'call-journal.json\').exists() else None\njournal=json.loads(raw_journal) if raw_journal else []\nprint(json.dumps({\'checked_at_utc\':datetime.now(UTC).isoformat(),\'run_id\':\'resolvedesk-cuda-eval-002\',\n    \'status\':actual[\'status\'] if actual else \'starting\',\'completed_records\':count,\'expected_records\':96,\n    \'completed_by_arm\':by_arm,\'process_return_code\':eval_process.poll(),\n    \'journal_entries\':len(journal),\'journal_statuses\':dict(Counter(e[\'status\'] for e in journal)),\n    \'pending_case\':actual.get(\'pending_case\') if actual else None,\n    \'interruption\':actual.get(\'interrupted_case_error\') if actual else None,\n    \'runtime_stop_timer_alive\':rd_runtime_stop_timer.is_alive(),\n    \'process_deadline_utc\':PROCESS_DEADLINE_UTC,\'runtime_stop_utc\':RUNTIME_STOP_UTC},indent=2),flush=True)\nconsole=output_dir/\'evaluation-console.log\'\nif console.exists(): print(\'Console tail (diagnostic only):\\n\'+console.read_text(errors=\'replace\')[-1800:])\nnames=[\'analysis-plan.json\',\'artifact-identity.json\',\'execution-addendum.json\',\'human-compute-authorization.json\',\n       \'evaluation-launch.json\',\'budgeted-run-start.json\',\'evaluation-console.log\',\'prelaunch-cpu-console.log\',\n       \'evaluation.json\',\'evaluation-partial.json\',\'call-journal.json\',\'protocol-audit.json\',\'process-deadline-stop.json\']\nfiles={}\nfor name in names:\n    path=output_dir/name\n    if not path.is_file():continue\n    raw=raw_status if path==status_path else raw_journal if name==\'call-journal.json\' else path.read_bytes()\n    files[\'reports/cuda-eval2/\'+name]=raw\nfiles[\'colab-execution/resource-guard.json\']=Path(\'/content/resolvedesk-resource-guard.json\').read_bytes()\nfiles[\'colab-source-manifest.json\']=(workspace/\'colab-source-manifest.json\').read_bytes()\nwith zipfile.ZipFile(\'/content/resolvedesk-eval2-metered-overlay.zip\') as source_overlay:\n    files[\'colab-execution/execution-overlay-manifest.json\']=source_overlay.read(\'execution-overlay-manifest.json\')\nreceipt={\'run_id\':\'resolvedesk-cuda-eval-002\',\'snapshot_at_utc\':datetime.now(UTC).isoformat(),\n         \'completed_records\':count,\'completed_by_arm\':by_arm,\'process_return_code\':eval_process.poll(),\n         \'analysis_plan_sha256\':EXPECTED_PLAN_SHA256,\n         \'execution_addendum_sha256\':\'e6e72a162af8c140a83ef9cf4c13102c24afb7428905ade797e98463d14c0e3e\',\n         \'files\':{name:hashlib.sha256(raw).hexdigest() for name,raw in files.items()},\n         \'scope\':\'Separate atomic report/journal reads; retain every in-flight tail. No replay or complete-results claim.\'}\nbuffer=io.BytesIO()\nwith zipfile.ZipFile(buffer,\'w\',zipfile.ZIP_DEFLATED) as archive:\n    for name,raw in files.items():archive.writestr(name,raw)\n    archive.writestr(\'snapshot-receipt.json\',json.dumps(receipt,indent=2))\nblob=buffer.getvalue();stamp=datetime.now(UTC).strftime(\'%Y%m%dT%H%M%S%fZ\')\nprint(json.dumps({\'snapshot_file\':\'resolvedesk-cuda-eval2-\'+stamp+\'.zip\',\'bytes\':len(blob),\'zip_sha256\':hashlib.sha256(blob).hexdigest(),\'completed_records\':count}),flush=True)\ndisplay(HTML(\'<a download="resolvedesk-cuda-eval2-\'+stamp+\'.zip" href="data:application/zip;base64,\'+base64.b64encode(blob).decode()+\'">Download new round2 evidence snapshot</a>\'))\n'
